// v062: retain one monochrome passenger, then replay the existing later trips.
// Equal command text does not imply equal passengers; only a full board match
// closes a replacement. The next call resumes the scan without consuming RNG.
struct DeferredPassenger {
    int64_t calls=0,candidates=0,illegal=0,related_caps=0,unclosed=0,deadlines=0;
    int64_t replacements=0,saved=0,max_span=0,related_steps=0,scanned=0;
    int64_t accepted_saved=0,best_created=0,budget_skips=0;
    double seconds=0;
    size_t cursor=0;
    static bool legal(const Board& board,Move m) {
        if(m.p<0||m.p>=geo.V||m.d>=4||m.l<1||m.l>8||m.l>m.k+1)return false;
        const int q=geo.ray[m.p][m.d][m.l],h=height(board[m.p]);
        return q>=0&&m.k<h&&height(board[q])+h-m.k<=8;
    }
    bool attempt(const Board& entry,const vector<Move>& answer,int first,double deadline,int& end,Move& direct) {
        if(first+1>=int(answer.size()))return false;
        const Move a=answer[first],b=answer[first+1];
        const int middle=geo.ray[a.p][a.d][a.l];
        const Word cargo=entry[a.p]>>(4*a.k);
        if(height(cargo)<2||monoColor(cargo)<=0||b.p!=middle||b.d!=a.d||
           int(a.l)+b.l>int(a.k)+2||int(a.l)+b.l>8)return false;
        Board original=entry,changed=entry;
        geo.apply(original,a);
        // Both old hops must transport exactly this parcel, not the landing stack.
        if((original[b.p]>>(4*b.k))!=cargo||b.k!=height(entry[middle]))return false;
        ++candidates;
        direct={a.p,uint8_t(a.k+1),a.d,uint8_t(a.l+b.l)};
        if(!legal(changed,direct)){++illegal;return false;}
        geo.apply(original,b);geo.apply(changed,direct);
        int related=2;
        for(int t=first+2;;t++) {
            if(original==changed) {
                end=t;max_span=max(max_span,int64_t(t-first));related_steps+=related;
                return true;
            }
            if(t==int(answer.size())){++unclosed;return false;}
            if((t&7)==0&&clk.elapsed()>=deadline){++deadlines;return false;}
            const Move m=answer[t];const int q=geo.ray[m.p][m.d][m.l];
            // Count dependencies from actual tower contents, not changed text.
            if(original[m.p]!=changed[m.p]||original[q]!=changed[q]) {
                if(++related>32){++related_caps;return false;}
            }
            if(!legal(changed,m)){++illegal;return false;}
            geo.apply(original,m);geo.apply(changed,m);++scanned;
        }
    }
    bool pass(vector<Move>& answer,double deadline) {
        ++calls;if(answer.size()<2)return false;
        cursor%=answer.size();Board prefix_board=geo.initial;
        for(int first=0;first+1<int(answer.size());first++) {
            if(clk.elapsed()>=deadline){cursor=size_t(first);++deadlines;return false;}
            if(size_t(first)>=cursor) {
                int end=-1;Move direct{};
                if(attempt(prefix_board,answer,first,deadline,end,direct)) {
                    // Replay through end has checked every changed operation.
                    // The remaining suffix starts from exactly the same board.
                    answer[first]=direct;answer.erase(answer.begin()+first+1);
                    cursor=0;++replacements;++saved;return true;
                }
            }
            geo.apply(prefix_board,answer[first]);++scanned;
        }
        cursor=0;return false;
    }
    void candidate(vector<Move>& answer,size_t best,int iteration,double start,double finish) {
        if(iteration%8||answer.size()>best+2)return;
        const double begin=clk.elapsed();
        const double available=0.01*max(PROGRAM_TIME_LIMIT_SEC*0.02,begin-start)-seconds;
        if(available<PROGRAM_TIME_LIMIT_SEC*0.00005||begin>=finish){++budget_skips;return;}
        pass(answer,min(finish,begin+min(available,PROGRAM_TIME_LIMIT_SEC*0.001)));
        seconds+=clk.elapsed()-begin;
    }
    void summary() const {
        LOCAL_NOTE(
            auto count=[&](const string& key,int64_t n){trace.count_by("deferred_passenger_"+key,n);};
            count("calls",calls);count("candidates",candidates);count("illegal",illegal);
            count("related_caps",related_caps);count("unclosed",unclosed);count("deadlines",deadlines);
            count("replacements",replacements);count("saved",saved);count("max_span",max_span);
            count("related_steps",related_steps);count("scanned",scanned);count("budget_skips",budget_skips);
            count("accepted_saved",accepted_saved);count("best_created",best_created);
            trace.add_time_ms("deferred_passenger",seconds*1000);
        )
    }
} deferred_passenger;

